export function ReviewEmbed({
  platform = "{{platform}}",
  reviewerName = "{{reviewerName}}",
  reviewText = "{{reviewText}}",
  reviewCount = {{reviewCount}},
}) {
  const markColor = { Google: "#4285F4", Trustpilot: "#00B67A", Facebook: "#1877F2" }[platform] ?? "#4285F4";
  return (
    <div style={{ font: "15px system-ui, sans-serif", color: "#241430", maxWidth: 320, padding: 20, borderRadius: 14,
      border: "1px solid #24143022", background: "#FAF7F2" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
        <span style={{ fontWeight: 800, fontSize: 13, textTransform: "uppercase", letterSpacing: "0.04em",
          padding: "3px 9px", borderRadius: 6, color: "#FAF7F2", background: markColor }}>{platform}</span>
        <span aria-label="5 out of 5 stars" style={{ color: "#E8A020", letterSpacing: 2 }}>&#9733;&#9733;&#9733;&#9733;&#9733;</span>
      </div>
      <p style={{ margin: "0 0 12px", color: "#241430dd" }}>&ldquo;{reviewText}&rdquo;</p>
      <p style={{ margin: 0, fontSize: 13, color: "#241430aa" }}><strong>{reviewerName}</strong> &middot; {reviewCount} reviews on {platform}</p>
    </div>
  );
}
